(●ˇ∀ˇ●)


原题链接
Insertion
Sort List
解题思路
这是一道数据结构题，按照题目要求进行操作即可。
复杂度分析
时间复杂度：O(n2)
空间复杂度：O(1)
代码
/**

Definition for singly-linked list.
struct ListNode {
int val;
ListNode *next;
ListNode(int x) : val(x), next(NULL) {}
};
/
class Solution {
private:
ListNode moveNextNode(ListNode*&amp; head) {
if (head == NULL)    return NULL;ListNode* current = head;head = head-&gt;next;current-&gt;next = NULL;return current;
}
ListNode insertSortedList(ListNode node, ListNode* sorted)
{
if (sorted == NULL)    return node;if (node == NULL)    return sorted;if (sorted-&gt;val &gt;= node-&gt;val) &#123;    node-&gt;next = sorted;    return node;&#125;ListNode* pre = sorted;while (pre-&gt;next != NULL &amp;&amp; pre-&gt;next-&gt;val &lt; node-&gt;val)    pre = pre-&gt;next;node-&gt;next = pre-&gt;next;pre-&gt;next = node;return sorted;
}

public:
ListNode insertionSortList(ListNode head) {
if (head == NULL || head-&gt;next == NULL)
return head;
    ListNode* node = NULL;    ListNode* sorted = NULL;    while (head != NULL) &#123;        node = moveNextNode(head);        sorted = insertSortedList(node, sorted);    &#125;    return sorted;&#125;
};

