概述
在JS中可以像操作对象一样操作函数，故而可以在JS中应用函数式编程技术。
使用函数处理数组
假设有一个数组，数组元素是数字，我们想要计算这些元素的平均值和标准差。若使用非函数式编程风格的话，代码是这样：
var data = [1, 1, 3, 5, 5];// 计算均值var total = 0;for (var i=0; i&lt;data.length; i++) total += data[i];var mean = total / data.length;// 计算标准差total = 0;for (var i=0; i&lt;data.length; i++) &#123;    var deviation = data[i] - mean;    total += deviation * deviation;&#125;var stddev = Math.sqrt(total / (data.length-1));
而对应的函数式编程，就会变得简洁如斯：
// 定义两个简单的函数var sum = function(x, y) &#123; return x+y; &#125;var square = function(x) &#123; return x*x; &#125;// 将这些函数和数组方法配合使用计算出平均数和标准差var data = [1, 1, 3, 5, 5];var mean = data.reduce(sum) /  data.length;var deviation = data.map(function(x) &#123; return x-mean; &#125;);var stddev = Math.sqrt(deviation.map(square).reduce(sum) / (data.length-1));
在ES3中，我们可以如下模拟map()和reduce()函数：
// 对于每个数组元素调用函数`f()`，并返回一个结果数组// 如果Array.prototype.map定义了的话，就使用该方法var map = Array.prototype.map          ? function(a, f) &#123; return a.map(f); &#125;          : function(a, f) &#123;              var results = [];              for (var i=0, len=a.length; i&lt;len; i++) &#123;                  if (i in a) results[i] = f.call(null, a[i], i, a);              &#125;              return results;          &#125;// 如果函数`f()`和可选的初始值将数组`a`减至一个值// 如果`Array.prototype.reduce`存在的话，就使用这个方法var reduce = Array.prototype.reduce             ? function(a, f, initial) &#123;                 if (arguments.length &gt; 2) &#123;                     return a.reduce(f, initial);                     else return a.reduce(f);                 &#125;             &#125;             : function(a, f, initial) &#123;                 var i = 0;                 var length = a.length;                 var accumulator;                 // 以特定的初始值开始，否则第一个值取自`a`                 if (arguments.length &gt; 2) accumulator = initial;                 else &#123; // 找到数组中第一个已定义的索引                    if (len === 0) throw TypeError();                    while (i &lt; len) &#123;                        if (i in a) &#123;                            accumulator = a[i++];                            break;                        &#125;                        else i++;                    &#125;                    if (i == len) throw TypeError();                 &#125;                 // 对于数组中剩下的元素依次调用函数`f()`                 while (i &lt; len) &#123;                    if (i in a)                         accumulator = f.call(undefined, accumulator, a[i], i, a);                    i++;                 &#125;                 return accumulator;             &#125;;// 使用实例var data = [1, 1, 3, 5, 5];var sum = function(x, y) &#123; return x+y; &#125;var square = function(x) &#123; return x*x; &#125;var mean = reduce(data, sum) / data.length; // !herevar deviation = map(data, function(x) &#123; return x-mean; &#125;);var stddev = Math.sqrt(reduce(map(deviation, square), sum)) / (data.length-1);
高阶函数
高阶函数就是操作函数的函数，它接收一个或多个函数作为参数，并返回一个新的函数。如：
// 该函数返回一个新的函数// 这个函数将它的实参传入`f()`// 并返回`f`的返回值的逻辑非function not(f) &#123;    return function() &#123;        var result = f.apply(this, arguments);        return !result;    &#125;&#125;var even = function(x) &#123; // 判断`a`是否为偶数的函数    return x % 2 === 0;&#125;;var odd = not(even);[1, 1, 3, 5, 5].every(odd);
下面再介绍函数mapper，这个函数接收一个函数作为参数，并返回一个新参数，新的参数将一个数组映射到另一个使用这个函数的数组上。
// 所返回的函数的参数应当是一个实参数组// 并对每一个数组元素执行函数f()// 并返回所有计算结果组成的数组function mapper(f) &#123;    return function(a) &#123; return map(a, f); &#125;&#125;var increment = function(x) &#123; return x+1; &#125;var incrementer = mapper(increment);incrementer([1, 2, 3]); // =&gt; [2, 3, 4]
更常用的例子是，它接收两个函数f()和g()，并返回一个新的函数用以计算f(g())：
// 返回一个新的可以计算`f(g(...))`的函数// 返回的函数`h()`将它所有的实参传入`g()`// 然后将`g()`的返回值传入`f()`// 调用`f()`和`g()`时的`this`值和调用`h()`时的`this`是同一个`this`function compose(f, g) &#123;    return function() &#123;        return f.call(this, g.apply(this, arguments));    &#125;&#125;var square = function(x) &#123; return x*x; &#125;var sum = function(x, y) &#123; return x+y; &#125;var squareofsum = compose(square, sum);squareofsum(2, 3); // =&gt; 25
不完全函数
函数f()的bind()方法返回一个新函数，给新函数传入特定的上下文和一组指定的参数，然后调用函数f()。我们说它把函数绑定至对象并传入一部分参数。bind()方法只是将实参放在（完整实参列表的）左侧，也就是说传入bind()的实参都是放在传入原始函数的实参列表开始的位置，但有时我们期望将传入bind()的实参放在（完整实参列表的）右侧：
// 实现一个工具函数间类数组对象转换为真正的数组function array(a, n) &#123; return Array.prototype.slice.call(a, n || 0); &#125;// 这个函数的实参传递至左侧function partialLeft(f /*, ...*/) &#123;    var args = arguments; // 保存外部的实参数组    return function() &#123;        var a = array(args, 1);               // 开始处理外部的第一个args        a = a.concat(array(arguments));       // 然后增加所有的内部实参        return f.apply(this, a);              // 然后基于这个实参列表调用f()    &#125;;&#125;// 这个函数的实参传递至右侧function partialRight(f /*, ...*/) &#123;    var args = arguments;    return function() &#123;        var a = array(arguments); // 从内部参数开始        a = a.concat(array(args, 1)); // 然后从外部第一个args开始添加        return f.apply(this, a);    &#125;;&#125;// 这个函数的实参被用作模板// 实参列表中的undefined值都被填充function partial(f /*, ...*/) &#123;    var args = arguments;    return function() &#123;        var a = array(args, 1); // 从外部args开始        var i = 0;        var j = 0;        // 遍历args，从内部实参填充undefined值        for (; i&lt;a.length; i++)            if (a[i] === undefined) a[i] = arguments[j++];        // 将剩下的内部实参都追加进去        a = a.concat(array(arguments, j));        return f.apply(this, a);    &#125;;&#125;// 这个函数带有三个实参var f = function(x, y, z) &#123; return x * (y - z); &#125;partialLeft(f, 2)(3, 4); // 绑定第一个实参 2 * (3 - 4) =&gt; -2partialRight(f, 2)(3, 4); // 绑定最后一个实参 3 * (4 - 2) =&gt; 6partial(f, undefined, 2)(3, 4); // 绑定中间的实参 3 * (2 - 4) =&gt; -6
我们也可以使用不完全调用的组合来重新组织求平均数和标准差的代码，这种编程风格是非常纯粹的函数式编程，也很难懂：
var data = [1, 1, 3, 5, 5];var sum = function(x, y) &#123; return x+y; &#125;var product = function(x, y) &#123; return x*y; &#125;var neg = partial(product, -1);var square = partial(Math.pow, undefined, 2);var sqrt = partial(Math.pow, undefined, .5);var reciprocal = partial(Math.pow, undefined, -1);// 现在计算均值和标准差，所有的函数调用都不带运算符var mean = product(reduce(data, sum), reciprocal(data.length));var stddev = sqrt(product(reduce(map(data,                                     compose(square,                                             partial(sum, neg(mean)))),                                sum),                         reciprocal(sum(data.length, -1))));
记忆
// 计算阶乘，并将结果缓存至函数的属性中function factorial(n) &#123;    if (isFinite(n) &amp;&amp; n&gt;0 &amp;&amp; n == Math.round(n)) &#123;        if (!(n in factorial)) &#123; // 如果没有缓存结果，计算结果并缓存之            factorial[n] = n * factorial(n-1);        &#125;        return factorial[n];    &#125;    else return NaN;&#125;factorial[1] = 1;
上例中，我们定义了函数factorial，它将计算结果缓存起来。在函数式编程中，这种缓存技巧被称为记忆。
// 返回f()的带有记忆功能的版本// 只有当f()的实参的字符串表示都不相同时它才会工作function memorize(f) &#123;    var cache = &#123;&#125;; // 将值保存在闭包内    return function() &#123;        // 将实参转换为字符串形式，并将其用作缓存的键        var key = arguments.length + Array.prototype.join.call(arguments, &#x27;,&#x27;);        if (key in cache) return cache[key];        else return cache[key] = f.apply(this, arguments);    &#125;;&#125;
上述memorize()函数创建一个新的对象，这个对象被当作缓存并赋值给一个局部变量，因此对于返回的函数来说它是私有的。所返回的函数将它的实参数组转换成字符串，并将字符串用作缓存对象的属性名。如果在缓存中存在这个值，则直接返回它；否则，就调用既定的函数对实参进行计算，将计算结果缓存起来并返回：
function gcd(a, b) &#123;    var t;    if (a &lt; b) t=b, b=a, a=t;    while(b != 0) t=b, b=a%b, a=t;    return a;&#125;var gcdmemo = memorize(gcd);gcdmemo(85, 187); // =&gt; 17// 注意，当我们实现一个递归函数时，往往需要实现记忆功能var factorial = memorize(function(n) &#123;                            return (n &lt;= 1) ? 1 : n * factorial(n-1);                         &#125;);factorial(5); // =&gt; 120
